import React, { useState } from "react";

export default function AdminDashboard({ reports, token, setMsg }) {
  const [ngos, setNgos] = useState(null);
  const [eventStats, setEventStats] = useState(null);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  // Generic fetch handler
  const loadData = async (endpoint, setter, errMsg) => {
    if (!token) return setMsg("Login as admin first");
    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) throw new Error(errMsg);
      const data = await res.json();
      setter(data.ngos || data.events || []);
    } catch (e) {
      console.error(e);
      setMsg(e.message || errMsg);
    }
  };

  return (
    <div className="panel">
      <h3>Admin Reports</h3>

      <div className="cards">
        <div className="stat-card">
          <div className="stat-num">
            {reports?.donations
              ? reports.donations.reduce((s, d) => s + parseFloat(d.amount || 0), 0)
              : "-"}
          </div>
          <div className="stat-label">Total Donation Amount (₹)</div>
        </div>
        <div className="stat-card">
          <div className="stat-num">{reports?.volunteers?.length || 0}</div>
          <div className="stat-label">Total Volunteers</div>
        </div>
        <div className="stat-card">
          <div className="stat-num">{reports?.feedbacks?.length || 0}</div>
          <div className="stat-label">Feedbacks</div>
        </div>
      </div>

      {/* ACTION BUTTONS */}
      <div style={{ marginTop: 12 }}>
        <button
          onClick={() => loadData("/api/actions/ngos", setNgos, "Failed to load NGOs")}
        >
          View Registered NGOs
        </button>

        <button
          style={{ marginLeft: 8 }}
          onClick={() =>
            loadData("/api/actions/registered-events", setEventStats, "Failed to load events")
          }
        >
          View Registered Events
        </button>

        <button
          style={{ marginLeft: 8 }}
          onClick={() =>
            loadData("/api/actions/event-stats", setEventStats, "Failed to load event stats")
          }
        >
          View Event Stats
        </button>
      </div>

      {/* EVENT STATISTICS (Moved here replacing Selected NGO section) */}
      <div style={{ width: 420, marginTop: 20 }}>
        <h4>Event Statistics</h4>
        {eventStats?.length ? (
          eventStats.map((ev) => (
            <div
              key={ev.id}
              style={{
                display: "flex",
                gap: 12,
                alignItems: "center",
                padding: 8,
                background: "#fff",
                borderRadius: 8,
                marginBottom: 8,
              }}
            >
              <img
                src={ev.image_url || "https://via.placeholder.com/120x80"}
                alt="ev"
                style={{ width: 100, height: 64, objectFit: "cover", borderRadius: 6 }}
              />
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 600 }}>{ev.title}</div>
                <div style={{ fontSize: 13, color: "#666" }}>
                  Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}
                </div>
              </div>
            </div>
          ))
        ) : (
          <p>No event data loaded.</p>
        )}
      </div>

      {/* NGO LIST (Still required on screen) */}
      {ngos && (
        <div style={{ marginTop: 20 }}>
          <h4>Registered NGOs</h4>
          {ngos.length ? (
            ngos.map((n) => (
              <div
                key={n.id}
                style={{
                  padding: 8,
                  background: "#fff",
                  borderRadius: 8,
                  marginBottom: 8,
                }}
              >
                <strong>{n.name}</strong>
                <div style={{ fontSize: 13, color: "#666" }}>{n.email}</div>
              </div>
            ))
          ) : (
            <p>No NGOs registered.</p>
          )}
        </div>
      )}
    </div>
  );
}
